class Date:
    def __init__(self, year, month, day):
        self.year = year
        self.month = month
        self.day = day

    @classmethod
    def from_string(cls, date_str):
        year, month, day = map(int, date_str.split("-"))
        return cls(year, month, day)  # Alternative Factory Constructor

    @staticmethod
    def is_valid_year(year):
        return year > 0

d = Date.from_string("2026-09-26")
print(Date.is_valid_year(2026))  # Output: True

